324	// Pixel-edge outlines of one segment value inside a candidate's block, as SVG path data in image coordinates.
325	function outline(c, blk, val) {
326	  const { h, w, x0, y0 } = c; let d = "";
327	  const at = (y, x) => (y >= 0 && y < h && x >= 0 && x < w ? blk[y * w + x] : 0);
328	  const isv = val === 2 ? (v) => v === 2 || v === 3 : (v) => v === val;
329	  for (let y = 0; y <= h; y++) { // horizontal edges between rows y-1 and y
330	    let run = -1;
331	    for (let x = 0; x <= w; x++) {
332	      const e = x < w && isv(at(y - 1, x)) !== isv(at(y, x));
333	      if (e && run < 0) run = x;
334	      if (!e && run >= 0) { d += `M${x0 + run} ${y0 + y}h${x - run}`; run = -1; }
335	    }
336	  }
337	  for (let x = 0; x <= w; x++) { // vertical edges between columns x-1 and x
338	    let run = -1;
339	    for (let y = 0; y <= h; y++) {
340	      const e = y < h && isv(at(y, x - 1)) !== isv(at(y, x));
341	      if (e && run < 0) run = y;
342	      if (!e && run >= 0) { d += `M${x0 + x} ${y0 + run}v${y - run}`; run = -1; }
343	    }
344	  }
345	  return d;
346	}
