593	  let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
594	  const take = (p) => { const [u, v] = toUV(p); u0 = Math.min(u0, u); u1 = Math.max(u1, u); v0 = Math.min(v0, v); v1 = Math.max(v1, v); };
595	  for (let y = 0; y < c.h; y++) for (let x = 0; x < c.w; x++) if (c.blk[y * c.w + x]) for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) take([c.x0 + x + dx, c.y0 + y + dy]);
596	  if (L) for (const k of ["length", "red"]) L[k].forEach(take);
597	  u0 -= pad; u1 += pad; v0 -= pad; v1 += pad;
598	  const uw = u1 - u0, vw = v1 - v0, s = Math.max(2, Math.min(size / 10, size / Math.max(uw, vw))), dpr = devicePixelRatio || 1;
599	  const cv = document.createElement("canvas"); cv.width = Math.round(uw * s * dpr); cv.height = Math.round(vw * s * dpr);
600	  cv.style.width = uw * s + "px"; cv.style.height = vw * s + "px";
601	  const ctx = cv.getContext("2d"); ctx.imageSmoothingEnabled = false;
602	  ctx.fillStyle = "#000"; ctx.fillRect(0, 0, cv.width, cv.height);
603	  ctx.setTransform(s * dpr, 0, 0, s * dpr, 0, 0); ctx.translate(-u0, -v0);
604	  ctx.transform(ax[0], nv[0], ax[1], nv[1], 0, 0); ctx.translate(-cx, -cy);
605	  const R = Math.ceil(Math.hypot(uw, vw) / 2) + 2, sx = Math.max(0, Math.floor(cx - R)), sy = Math.max(0, Math.floor(cy - R));
606	  const sw = Math.min(st.W, Math.ceil(cx + R)) - sx, sh = Math.min(st.H, Math.ceil(cy + R)) - sy;
607	  ctx.drawImage(st.plain, sx, sy, sw, sh, sx, sy, sw, sh);
608	  if (o.borders) {
609	    ctx.lineWidth = 1 / s; ctx.strokeStyle = result(c.i) === null ? st.show.passC : st.show.failC;
610	    for (const [val, alpha] of [[1, 0.5], [2, 0.7]]) { ctx.globalAlpha = alpha; ctx.stroke(new Path2D(outline(c, c.blk, val))); }
611	    ctx.globalAlpha = 1;
612	  }
613	  const node = document.createElement("div"); node.className = "crop"; node.append(cv);
614	  if (L && (o.bars || o.lenImg || o.adjust)) node.append(cropMarks(c, L, { s, u0, v0, uw, vw, toUV, toXY, ax }));
615	  st.crops.set(c.i + "|" + size, { key, node }); return node;
616	}
617	
618	// bars, length labels and draggable ends over a crop, in its own turned coordinates
619	function cropMarks(c, L, g) {
620	  const o = st.opt, f = st.um || 1, svg = el("svg", { class: "marks", viewBox: `${g.u0} ${g.v0} ${g.uw} ${g.vw}`, width: g.uw * g.s, height: g.vw * g.s });
621	  const px = 1 / g.s, line = (k, cls) => { const [[a, b], [p, q]] = L[k].map(g.toUV); return el("line", { x1: a, y1: b, x2: p, y2: q, class: cls }); };
622	  const draw = () => {
623	    svg.replaceChildren();
624	    if (o.bars) svg.append(line("length", "bar"), line("width", "bar"), line("red", "bar r"));
625	    if (o.lenImg) {
626	      for (const [k, cls, dy] of [["length", "", -5], ["red", "r", 11]]) {
627	        const [[a, b], [p, q]] = L[k].map(g.toUV), t = el("text", { x: (a + p) / 2, y: Math.min(b, q) + dy * px, class: cls, "font-size": 10 * px, "stroke-width": 2 * px });
628	        t.textContent = fmt(dist(L[k]) * f, 1); svg.append(t);
629	      }
630	    }
631	    if (o.adjust && result(c.i) === null) for (const k of ["length", "red"]) L[k].forEach((p, j) => {
632	      const [u, v] = g.toUV(p), h = el("circle", { cx: u, cy: v, r: 4 * px, class: "handle" + (k === "red" ? " r" : ""), "stroke-width": px });
633	      h.dataset.k = k; h.dataset.j = j; svg.append(h);
634	    });
635	  };
636	  draw();
637	  // an end slides along its own line; the result is kept in image coordinates
638	  svg.addEventListener("pointerdown", (e) => {
639	    const h = e.target.closest(".handle"); if (!h) return;
640	    e.preventDefault(); e.stopPropagation(); svg.setPointerCapture(e.pointerId);
641	    const k = h.dataset.k, j = +h.dataset.j, [A, B] = L[k], d = [B[0] - A[0], B[1] - A[1]], n = Math.hypot(...d), dir = [d[0] / n, d[1] / n];
642	    L = { ...L, [k]: [[...A], [...B]] };
643	    const move = (ev) => {
644	      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
645	      const q = pt.matrixTransform(svg.getScreenCTM().inverse()), P = g.toXY([q.x, q.y]);
646	      let t = (P[0] - A[0]) * dir[0] + (P[1] - A[1]) * dir[1];
647	      t = j === 0 ? Math.min(t, n - 1) : Math.max(t, 1);
648	      L[k][j] = [A[0] + t * dir[0], A[1] + t * dir[1]]; draw();
649	    };
650	    const up = () => {
651	      svg.removeEventListener("pointermove", move); svg.removeEventListener("pointerup", up);
652	      edit(c.i, { [k]: L[k].map((p) => p.map((v) => Math.round(v * 100) / 100)) });
653	    };
654	    svg.addEventListener("pointermove", move); svg.addEventListener("pointerup", up);
655	  });
656	  return svg;
657	}
658	const autoPad = () => Math.max(4, Math.round((st.meta && st.meta.unit) || 4));
659	
660	const GOTO = `<svg viewBox="0 0 24 24" width="16" height="16"><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2" class="dot"/><path d="M12 1.5v4M12 18.5v4M1.5 12h4M18.5 12h4"/></svg>`;
661	function card(c, where) {
662	  const r = result(c.i), f = st.forced.get(c.i), d = document.createElement("div");
663	  d.className = "card " + (r === null ? "pass" : "fail") + (f === "in" ? " approved" : f === "out" ? " byyou" : "");
664	  const state = f === "in" ? "Approved" : f === "out" ? "Rejected by you" : r === null ? "Finalist" : "Rejected";
665	  d.innerHTML = `<div class="head"><span class="num">#${st.numbers.get(c.i)}</span><span class="state">${state}</span><span class="acts"></span></div>`;
666	  const acts = d.querySelector(".acts");
667	  const btn = (label, title, on, fn, cls = "") => {
668	    const b = document.createElement("button"); b.textContent = label; b.title = title; b.className = cls + (on ? " on" : "");
669	    b.setAttribute("aria-pressed", on); b.onclick = fn; acts.append(b);
670	  };
671	  btn("✅", f === "in" ? "Approved: click to undo" : "Approve: a real NoR, with the lengths shown (saved as ground truth)", f === "in",
672	    () => decide(c.i, f === "in" ? null : "approve"), "emoji");
673	  if (f === "out") btn("Un-reject", "Let the filters decide again", false, () => decide(c.i, null), "text");
674	  else btn("❌", "Reject: not a NoR (saved as ground truth)", false, () => decide(c.i, "reject"), "emoji");
675	  const wrap = document.createElement("div"); wrap.className = "crop-wrap";
676	  wrap.append(crop(c, where === "selected" ? 320 : 170));
677	  wrap.insertAdjacentHTML("beforeend", `<button class="goto" title="Show it on the image" aria-label="Show it on the image">${GOTO}</button>`);
678	  wrap.querySelector(".goto").onclick = () => { select(c.i); showView("image"); focusOn(c); };
679	  d.append(wrap);
680	  const e = st.edits.get(c.i) || {};
681	  if (e.length || e.red) {
682	    d.insertAdjacentHTML("beforeend", `<div class="tag">Lengths adjusted <button class="link">reset</button></div>`);
683	    d.querySelector(".tag button").onclick = () => edit(c.i, { length: null, red: null });
684	  }
685	  if (r !== null) d.insertAdjacentHTML("beforeend", `<div class="why">${whyAll(c).map((k) => `<span><b class="lt" style="--c:${colour(k)}">${reasonOf(k).letter}</b> ${esc(reasonOf(k).title)}</span>`).join("")}</div>`);
686	  if (st.opt.lenCard && c.m) {
687	    const t = document.createElement("table");
688	    t.innerHTML = measures(c).map(([l, v]) => `<tr><td>${l}</td><td>${fmt(v)}</td></tr>`).join("");
689	    d.append(t);
690	  }
691	  return d;
692	}
693	
694	function renderList() {
695	  const items = st.tab === "pass" ? st.passes || [] : st.rejects || [];
696	  $("#list").replaceChildren(...items.map((c) => card(c, "list")));
697	  if (!items.length) $("#list").innerHTML = `<p class="dim">${st.tab === "pass" ? "No finalists." : "Nothing rejected."}</p>`;
698	}
699	
700	// ---------- selection ----------
701	function select(i) {
702	  st.sel = i; renderSelected(); placeRing();
703	}
704	function renderSelected() {
705	  const c = st.sel == null ? null : st.cands[st.sel];
706	  $("#selected").classList.toggle("dim", !c);
707	  $("#selected").replaceChildren(c ? card(c, "selected") : "Click a candidate on the image.");
708	  $("#sel-prev").disabled = $("#sel-next").disabled = !st.order.length;
709	}
710	function placeRing() {
711	  if (!st.ring) return;
712	  const c = st.sel == null ? null : st.cands[st.sel];
713	  st.ring.style.display = c ? "" : "none";
714	  if (!c) return;
715	  const [a, b, cc, d] = c.bb;
716	  st.ring.setAttribute("cx", (a + cc) / 2); st.ring.setAttribute("cy", (b + d) / 2);
717	  st.ring.setAttribute("r", Math.hypot(cc - a, d - b) / 2 + 4 / st.zoom);
718	}
719	// the next candidate by number among those on show
720	function step(dir) {
721	  const list = st.order.filter((c) => (result(c.i) === null ? st.show.pass : st.show.fails));
722	  if (!list.length) return;
723	  const k = list.findIndex((c) => c.i === st.sel);
724	  const c = list[k < 0 ? (dir > 0 ? 0 : list.length - 1) : (k + dir + list.length) % list.length];
725	  select(c.i); if (st.view === "image") focusOn(c);
726	}
727	$("#sel-prev").onclick = () => step(-1);
728	$("#sel-next").onclick = () => step(1);
729	
730	function stats(xs) {
731	  const v = xs.filter((x) => x != null && isFinite(x)).sort((a, b) => a - b), n = v.length;
732	  if (!n) return { n };
733	  const mean = v.reduce((a, b) => a + b, 0) / n, sd = Math.sqrt(v.reduce((a, b) => a + (b - mean) ** 2, 0) / Math.max(n - 1, 1));
734	  const med = n % 2 ? v[(n - 1) / 2] : (v[n / 2 - 1] + v[n / 2]) / 2;
735	  return { n, mean, sd, med, min: v[0], max: v[n - 1], v };
736	}
737	
738	function hist(label, s) {
739	  const W = 220, H = 70, bins = 20;
740	  if (!s.n) return "";
741	  const lo = s.min, hi = s.max === s.min ? s.min + 1 : s.max, cnt = new Array(bins).fill(0);
742	  for (const x of s.v) cnt[Math.min(bins - 1, Math.floor(((x - lo) / (hi - lo)) * bins))]++;
743	  const top = Math.max(...cnt), bw = W / bins;
744	  const bars = cnt.map((c, k) => `<rect x="${k * bw + 0.5}" y="${H - (c / top) * H}" width="${bw - 1}" height="${(c / top) * H}"><title>${c}</title></rect>`).join("");
745	  return `<div class="hist">${label}<br><svg width="${W}" height="${H + 14}"><g>${bars}</g>
746	    <text x="0" y="${H + 12}" fill="currentColor" font-size="10">${fmt(lo)}</text>
747	    <text x="${W}" y="${H + 12}" fill="currentColor" font-size="10" text-anchor="end">${fmt(hi)}</text></svg></div>`;
748	}
749	
750	function summaryRows(passes) {
751	  return MEASURES.map((_, k) => [measures(passes[0] || { m: {} })[k][0], stats(passes.map((c) => measures(c)[k][1]))]);
752	}
753	function renderSummary(passes, counts) {
754	  const rows = summaryRows(passes);
755	  st.counts = counts;
756	  const tbl = `<table><tr><th>measurement</th><th>n</th><th>mean</th><th>SD</th><th>median</th><th>min</th><th>max</th></tr>` +
757	    rows.map(([l, s]) => `<tr><td>${l}</td><td>${s.n}</td><td>${fmt(s.mean)}</td><td>${fmt(s.sd)}</td><td>${fmt(s.med)}</td><td>${fmt(s.min)}</td><td>${fmt(s.max)}</td></tr>`).join("") + "</table>";
758	  const reasons = Object.entries(counts).sort((a, b) => b[1] - a[1])
759	    .map(([k, n]) => `<b class="lt" style="--c:${colour(k)}">${reasonOf(k).letter}</b> ${esc(reasonOf(k).title)}: ${n}`).join(" · ");
760	  const scale = st.um ? `Scale from the file: ${st.um.toFixed(4)} µm per pixel.` : "No scale in the file, so lengths are in pixels.";
761	  $("#summary").classList.remove("dim");
762	  $("#summary").innerHTML = `<div>${passes.length} passing NoRs. ${scale}</div><div class="tbl">${tbl}</div>
763	    <div class="hists">${rows.map(([l, s]) => hist(l, s)).join("")}</div><div class="reasons">Rejected: ${reasons || "none"}</div>`;
764	}
765	
766	// ---------- downloads ----------
767	function downloads(on) { for (const id of ["#dl-cands", "#dl-summary", "#dl-truth"]) $(id).disabled = !on || !st.meta; }
768	const base = () => st.fileName.replace(/\.[^.]+$/, "") || "nors";
769	function save_(name, text, type) {
770	  const a = document.createElement("a");
771	  a.href = URL.createObjectURL(new Blob([text], { type })); a.download = name; a.click();
772	  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
773	}
774	const csvCell = (v) => (/[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : v);
775	const csv = (rows) => rows.map((r) => r.map(csvCell).join(",")).join("\n");
776	$("#dl-cands").onclick = () => {
777	  const u = st.um ? "um" : "px";
778	  const head = ["n", "x_px", "y_px", "status", "reason", "rejected_by", "decision", "lengths", ...MEASURES.map(([k, , s]) => (s ? `${k}_${u}` : k))];
779	  const rows = st.order.map((c) => {
780	    const r = result(c.i), f = st.forced.get(c.i);
781	    return [st.numbers.get(c.i), fmt(c.cx, 1), fmt(c.cy, 1), r === null ? "finalist" : "rejected", r === null ? "" : reasonOf(r).title,
782	      whyAll(c).map((k) => reasonOf(k).letter).join(" "), { in: "approved", out: "rejected by you" }[f] || "", measured(c) || "",
783	      ...measures(c).map(([, v]) => fmt(v, 3))];
784	  });
785	  save_(base() + "_candidates.csv", csv([head, ...rows]), "text/csv");
786	};
787	$("#dl-summary").onclick = () => {
788	  const rows = [["measurement", "n", "mean", "sd", "median", "min", "max"],
789	    ...summaryRows(st.passes).map(([l, s]) => [l, s.n, fmt(s.mean, 3), fmt(s.sd, 3), fmt(s.med, 3), fmt(s.min, 3), fmt(s.max, 3)]),
790	    [], ["rejected", "count"], ...Object.entries(st.counts).map(([k, n]) => [`${reasonOf(k).letter} ${reasonOf(k).title}`, n])];
791	  save_(base() + "_summary.csv", csv(rows), "text/csv");
792	};
793	// What a person decided on this image, for scoring finders in the lab (detection/nor_lab.py reads
794	// it with --labels): every finalist and every candidate the user decided on, with its lengths.
795	$("#dl-truth").onclick = () => {
796	  const labels = [];
797	  for (const c of st.order) {
798	    const r = result(c.i), f = st.forced.get(c.i), m = measured(c), L = linesOf(c), px = measuresPx(c);
799	    if (r !== null && !f) continue;
800	    labels.push({ id: st.numbers.get(c.i), x: c.cx, y: c.cy, label: r === null ? 1 : 0,
801	      source: f || m ? "user" : "finder", decision: { in: "approved", out: "rejected by you" }[f] || "accepted",
802	      measured: r === null ? m : null, length_px: px.length ?? null, red_length_px: px.red_length ?? null, width_px: px.width ?? null,
803	      lines: L ? { length: L.length, red: L.red } : null });
804	  }
805	  const out = { format: "norfinder-ground-truth/1", exported: new Date().toISOString(),
806	    image: { name: st.fileName, sha256: st.sha, width: st.W, height: st.H, um_per_px: st.um || null },
807	    finder: st.meta.finder, finder_settings: st.runOverrides || {}, filters: { values: st.values, off: [...st.off] }, labels };
808	  save_(base() + "_ground_truth.json", JSON.stringify(out, null, 1), "application/json");
809	};
810	
811	// ---------- the image view: drag to move, scroll up and down to zoom, sideways to step ----------
812	function focusOn(c) {
813	  const sc = $("#scroller");
814	  sc.scrollTo({ left: c.cx * st.zoom - sc.clientWidth / 2, top: c.cy * st.zoom - sc.clientHeight / 2, behavior: "smooth" });
815	}

