function renderList() {
  const items = st.tab === "pass" ? st.passes || [] : st.rejects || [];
  $("#list").replaceChildren(...items.map((c) => card(c, "list")));
  if (!items.length) $("#list").innerHTML = `<p class="dim">${st.tab === "pass" ? "No finalists." : "Nothing rejected."}</p>`;
