  st.ring.style.display = c ? "" : "none";
  if (!c) return;
  const [a, b, cc, d] = c.bb;
  st.ring.setAttribute("cx", (a + cc) / 2); st.ring.setAttribute("cy", (b + d) / 2);
  st.ring.setAttribute("r", Math.hypot(cc - a, d - b) / 2 + 4 / st.zoom);
