$("#sel-prev").onclick = () => step(-1);
$("#sel-next").onclick = () => step(1);

function stats(xs) {
  const v = xs.filter((x) => x != null && isFinite(x)).sort((a, b) => a - b), n = v.length;
  if (!n) return { n };
