    <text x="0" y="${H + 12}" fill="currentColor" font-size="10">${fmt(lo)}</text>
    <text x="${W}" y="${H + 12}" fill="currentColor" font-size="10" text-anchor="end">${fmt(hi)}</text></svg></div>`;
