// node drive.mjs REPO ANSWERS IMAGE OUTDIR [theme]
import { createRequire } from "node:module";
import fs from "node:fs"; import http from "node:http"; import path from "node:path";
const require = createRequire(import.meta.url);
const pw = require("/opt/node22/lib/node_modules/playwright");
const [repo, answers, image, out, theme = "dark"] = process.argv.slice(2);
fs.mkdirSync(out, { recursive: true });
const STAND_IN = `
const A = await (await fetch("answers/answers.json")).json();
const bin = async (n) => new Uint8Array(await (await fetch("answers/" + n)).arrayBuffer());
postMessage({ type: "ready", finders: A.finders, about: A.about, secs: 0 });
onmessage = async ({ data: m }) => {
  if (m.type === "open") { const images = await bin("images.bin"); postMessage({ type: "opened", H: A.H, W: A.W, um: A.um, images, secs: 0 }, [images.buffer]); }
  else if (m.type === "detect") { const seg = await bin("seg_tl.bin"); postMessage({ type: "detected", meta: A.detected.tl, seg, secs: 0 }, [seg.buffer]); }
  else if (m.type === "refilter") postMessage({ type: "filtered", ...A.filtered.tl[0], seq: m.seq, ms: 0 });
};`;
const TYPES = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml" };
const server = http.createServer((q, r) => {
  const u = decodeURIComponent(new URL(q.url, "http://x").pathname);
  if (u === "/web/worker.js") { r.writeHead(200, { "content-type": "text/javascript" }); return r.end(STAND_IN); }
  let f = u.startsWith("/web/answers/") ? path.join(answers, u.slice(13)) : path.join(repo, u);
  if (!fs.existsSync(f) || fs.statSync(f).isDirectory()) { r.writeHead(404); return r.end(); }
  r.writeHead(200, { "content-type": TYPES[path.extname(f)] || "application/octet-stream" }); fs.createReadStream(f).pipe(r);
});
await new Promise((ok) => server.listen(0, "[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]", ok));
const origin = `http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:${server.address().port}`;
const browser = await pw.chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1500, height: 950 } });
await ctx.route((u) => !u.href.startsWith(origin), (r) => r.abort());
await ctx.addInitScript((t) => { delete Navigator.prototype.serviceWorker; localStorage.setItem("nor-theme", t); }, theme);
const page = await ctx.newPage();
page.on("pageerror", (e) => console.log("PAGE ERROR", e.message));
page.on("console", (m) => m.type() === "error" && console.log("console", m.text()));
await page.goto(origin + "/web/index.html");
await page.waitForFunction(() => !document.querySelector("#finder").disabled);
await page.setInputFiles("#file", image);
await page.waitForFunction(() => !document.querySelector("#find").disabled);
await page.click("#find");
await page.waitForFunction(() => document.querySelector(".filter .n")?.textContent);
const shot = (n, el) => (el ? page.locator(el).screenshot({ path: `${out}/${n}.png` }) : page.screenshot({ path: `${out}/${n}.png` }));
await shot("1_filters", "#left");
// select a rejected candidate far down the list via the stepper
for (let k = 0; k < 30; k++) await page.click("#sel-next");
await page.click("#switch");
await page.waitForTimeout(400);
await shot("2_items_selected");
console.log("tab after switch:", await page.evaluate(() => document.querySelector("#tab-fail").classList.contains("on") ? "fail" : "pass"),
  "selected card in view:", await page.evaluate(() => { const d = document.querySelector("#list .card.selected"); if (!d) return "none"; const r = d.getBoundingClientRect(), v = document.querySelector("#items-view").getBoundingClientRect(); return r.top >= v.top && r.bottom <= v.bottom; }));
// thumbs up on another card in the list selects it
const other = page.locator("#list .card:not(.selected)").nth(2);
const oi = await other.getAttribute("data-i");
await other.locator(".verdict .down").click();
console.log("after thumbs-down, selected =", await page.evaluate(() => document.querySelector("#selected .card")?.dataset.i), "expected", oi);
await page.click("#tab-pass"); await page.waitForTimeout(200);
await page.locator("#list .card").nth(1).locator(".verdict .up").click();
await page.waitForTimeout(200);
await shot("3_finalists");
await page.locator("#list .card").first().screenshot({ path: `${out}/4_card_pass.png` });
await page.locator("#list .card.selected").screenshot({ path: `${out}/4b_card_selected.png` }).catch(() => console.log("no selected card on finalists"));
await page.click("#card-menu summary"); await shot("5_options_pass", "#view");
await page.click("#tab-fail"); await page.waitForTimeout(200);
await page.click("#card-menu summary"); await shot("6_options_fail", "#view");
await page.locator("#selected-box").screenshot({ path: `${out}/7_selected_box.png` });
await page.locator("#list .card").first().hover();
await page.locator("#list .card").first().locator(".verdict .up").hover();
await page.locator("#list .card").first().screenshot({ path: `${out}/8_hover_up.png` });
await browser.close(); server.close();
